$ErrorActionPreference = 'Continue'
Set-Location $PSScriptRoot

Write-Output '=== 1. limpieza de voz ==='
ffmpeg -hide_banner -loglevel error -y -i voz_cruda.wav -af "highpass=f=80,afftdn=nr=12:nf=-50,silenceremove=start_periods=1:start_threshold=-45dB:stop_periods=-1:stop_duration=0.25:stop_silence=0.12:stop_threshold=-45dB,atempo=1.08" -ar 48000 -ac 1 voz_limpia.wav
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 2. medir voz ==='
ffmpeg -hide_banner -nostats -i voz_limpia.wav -af "loudnorm=I=-16:TP=-1.5:LRA=11:print_format=json" -f null - 2>&1 | Select-Object -Last 12 | ForEach-Object { "$_" }

Write-Output '=== 3. normalizar voz (segunda pasada) ==='
ffmpeg -hide_banner -loglevel error -y -i voz_limpia.wav -af "loudnorm=I=-16:TP=-1.5:LRA=11:measured_I=-38.37:measured_TP=-28.51:measured_LRA=0.70:measured_thresh=-48.37:offset=0.08:linear=true" -ar 48000 -ac 1 voz.wav
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 4. musica a -20 LUFS ==='
ffmpeg -hide_banner -nostats -i musica.wav -af ebur128 -f null - 2>&1 | Select-String '^\s+I:' | ForEach-Object { "$_" }
ffmpeg -hide_banner -loglevel error -y -i musica.wav -af "volume=3.1dB" -ar 48000 -ac 2 musica_20.wav
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 5A. mezcla con atenuacion automatica ==='
$dur = [double](ffprobe -v error -show_entries format=duration -of csv=p=0 voz.wav)
$fin = [math]::Round($dur - 1.5, 2).ToString([cultureinfo]::InvariantCulture)
Write-Output "duracion=$dur  inicio del fundido=$fin"
ffmpeg -hide_banner -loglevel error -y -i voz.wav -stream_loop -1 -i musica_20.wav -i golpe.wav -i pitido.wav -filter_complex "
[0:a]aformat=sample_rates=48000:channel_layouts=stereo,asplit=2[voz][llave];
[1:a]aformat=sample_rates=48000:channel_layouts=stereo,afade=t=in:d=0.3,afade=t=out:st=${fin}:d=1.5[mus];
[mus][llave]sidechaincompress=threshold=0.03:ratio=2:attack=15:release=350[musduck];
[2:a]aformat=sample_rates=48000:channel_layouts=stereo,volume=-6dB,adelay=3200:all=1[fx1];
[3:a]aformat=sample_rates=48000:channel_layouts=stereo,volume=-10dB,adelay=9500:all=1[fx2];
[voz][musduck][fx1][fx2]amix=inputs=4:duration=first:normalize=0,alimiter=limit=0.891:attack=5:release=50:level=false[out]
" -map "[out]" -ar 48000 -c:a pcm_s16le mezcla.wav
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 5B. mezcla con musica a nivel fijo ==='
ffmpeg -hide_banner -loglevel error -y -i voz.wav -stream_loop -1 -i musica_20.wav -i golpe.wav -i pitido.wav -filter_complex "
[0:a]aformat=sample_rates=48000:channel_layouts=stereo[voz];
[1:a]aformat=sample_rates=48000:channel_layouts=stereo,volume=-8dB,afade=t=in:d=0.3,afade=t=out:st=${fin}:d=1.5[mus];
[2:a]aformat=sample_rates=48000:channel_layouts=stereo,volume=-6dB,adelay=3200:all=1[fx1];
[3:a]aformat=sample_rates=48000:channel_layouts=stereo,volume=-10dB,adelay=9500:all=1[fx2];
[voz][mus][fx1][fx2]amix=inputs=4:duration=first:normalize=0,alimiter=limit=0.891:attack=5:release=50:level=false[out]
" -map "[out]" -ar 48000 -c:a pcm_s16le mezcla_fija.wav
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 6. master a -14 LUFS, AAC ==='
ffmpeg -hide_banner -nostats -y -i mezcla.wav -af "loudnorm=I=-14:TP=-1.0:LRA=11:print_format=summary" -ar 48000 -c:a aac -b:a 192k audio_final.m4a 2>&1 | Select-String 'Integrated|True Peak|Normalization' | ForEach-Object { "$_" }
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 7. pegar al video ==='
ffmpeg -hide_banner -loglevel error -y -i video_mudo.mp4 -i audio_final.m4a -map 0:v:0 -map 1:a:0 -c:v copy -c:a copy -shortest -movflags +faststart short_final.mp4
Write-Output "exit=$LASTEXITCODE"

Write-Output '=== 8. comprobacion final ==='
foreach ($f in 'voz.wav','musica_20.wav','mezcla.wav','mezcla_fija.wav','short_final.mp4') {
  $l = ffmpeg -hide_banner -nostats -i $f -af ebur128=peak=true -f null - 2>&1 | Select-String '^\s+(I:|Peak:)' | ForEach-Object { "$_".Trim() -replace '\s+',' ' }
  $d = ffprobe -v error -show_entries format=duration -of csv=p=0 $f
  Write-Output ("{0,-16} {1}  {2}  dur={3}" -f $f, $l[0], $l[1], $d)
}
ffprobe -v error -show_entries stream=codec_name,sample_rate,channels,width,height -of compact=p=0 short_final.mp4

